#!/bin/sh
# Xcode Cloud runs this after cloning, before it builds. It takes no arguments. An app's
# ci_scripts/ci_post_clone.sh hands its name to its shim, which clones this release and runs this
# file from the app's root.
#
# Usage:   run by the app's shim; here, cd <app> && sh <this repo>/ci_scripts/ci_post_clone.sh
# Inputs:  the current folder, the app's root; ci_scripts/app_post_clone.sh, an optional step
#          the app owns, run first; project.yml, when the app generates its project.
# Outputs: the Xcode project, generated by XcodeGen 2.46.0: an installed copy of that version,
#          or else one downloaded and checked by its SHA-256. A repo that commits its project
#          skips this step.
#
# Xcode Cloud sets the build number to its run number at archive time, so nothing here
# changes it. XCODEGEN_URL may point at another copy of the same zip, such as a file:// URL.
set -eu

if [ -f ci_scripts/app_post_clone.sh ]; then
	sh ci_scripts/app_post_clone.sh
fi

[ -f project.yml ] || exit 0

XCODEGEN_VERSION=2.46.0
XCODEGEN_SHA256=4d9e34b62172d645eed6457cac13fc222569974098ef4ee9c3368bedf0196806
XCODEGEN_URL="${XCODEGEN_URL:-https://github.com/yonaskolb/XcodeGen/releases/download/$XCODEGEN_VERSION/xcodegen.zip}"

if command -v xcodegen >/dev/null 2>&1 && [ "$(xcodegen --version)" = "Version: $XCODEGEN_VERSION" ]; then
	exec xcodegen generate
fi

dir=$(mktemp -d)
trap 'rm -rf "$dir"' EXIT
curl -fsSL "$XCODEGEN_URL" -o "$dir/xcodegen.zip"
if ! echo "$XCODEGEN_SHA256  $dir/xcodegen.zip" | shasum -a 256 -c - >/dev/null; then
	echo "ci_post_clone: xcodegen.zip does not match XcodeGen $XCODEGEN_VERSION's SHA-256" >&2
	exit 1
fi
unzip -q "$dir/xcodegen.zip" -d "$dir"
"$dir/xcodegen/bin/xcodegen" generate
